   528  // perhaps we doubled two characters
   529  // (for example vacation -> vacacation)
   530  // The recognized pattern with regex back-references:
   531  // "(.)(.)\1\2\1" or "..(.)(.)\1\2"
   532
   533  int SuggestMgr::doubletwochars_utf(std::vector<std::string>& wlst,
   534                                     const w_char* word,
   535                                     int wl,
   536                                     int cpdsuggest) {
   537    int state = 0;
   538    if (wl < 5 || !pAMgr)
   539      return wlst.size();
   540    for (int i = 2; i < wl; i++) {
   541      if (word[i] == word[i - 2]) {
   542        state++;
   543        if (state == 3 || (state == 2 && i >= 4)) {
   544          std::vector<w_char> candidate_utf(word, word + i - 1);
   545          candidate_utf.insert(candidate_utf.end(), word + i + 1, word + wl);
   546          std::string candidate;
   547          u16_u8(candidate, candidate_utf);
   548          testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   549          state = 0;
   550        }
   551      } else {
   552        state = 0;
   553      }
   554    }
   555    return wlst.size();
   556  }
