   558  // error is wrong char in place of correct one (case and keyboard related
   559  // version)
   560  int SuggestMgr::badcharkey(std::vector<std::string>& wlst,
   561                             const char* word,
   562                             int cpdsuggest) {
   563    std::string candidate(word);
   564
   565    // swap out each char one by one and try uppercase and neighbor
   566    // keyboard chars in its place to see if that makes a good word
   567    for (size_t i = 0; i < candidate.size(); ++i) {
   568      char tmpc = candidate[i];
   569      // check with uppercase letters
   570      candidate[i] = csconv[((unsigned char)tmpc)].cupper;
   571      if (tmpc != candidate[i]) {
   572        testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   573        candidate[i] = tmpc;
   574      }
   575      // check neighbor characters in keyboard string
   576      if (ckey.empty())
   577        continue;
   578      size_t loc = 0;
   579      while ((loc < ckeyl) && ckey[loc] != tmpc)
   580        ++loc;
   581      while (loc < ckeyl) {
   582        if ((loc > 0) && ckey[loc - 1] != '|') {
   583          candidate[i] = ckey[loc - 1];
   584          testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   585        }
   586        if (((loc + 1) < ckeyl) && (ckey[loc + 1] != '|')) {
   587          candidate[i] = ckey[loc + 1];
   588          testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   589        }
   590        do {
   591          loc++;
   592        } while ((loc < ckeyl) && ckey[loc] != tmpc);
   593      }
   594      candidate[i] = tmpc;
   595    }
   596    return wlst.size();
   597  }
