   645  int SuggestMgr::badchar(std::vector<std::string>& wlst, const char* word, int cpdsuggest) {
   646    std::string candidate(word);
   647    clock_t timelimit = clock();
   648    int timer = MINTIMER;
   649    // swap out each char one by one and try all the tryme
   650    // chars in its place to see if that makes a good word
   651    for (size_t j = 0; j < ctryl; ++j) {
   652      for (std::string::reverse_iterator aI = candidate.rbegin(), aEnd = candidate.rend(); aI != aEnd; ++aI) {
   653        char tmpc = *aI;
   654        if (ctry[j] == tmpc)
   655          continue;
   656        *aI = ctry[j];
   657        testsug(wlst, candidate, cpdsuggest, &timer, &timelimit);
   658        if (!timer)
   659          return wlst.size();
   660        *aI = tmpc;
   661      }
   662    }
   663    return wlst.size();
   664  }
