   693  // error is word has an extra letter it does not need
   694  int SuggestMgr::extrachar_utf(std::vector<std::string>& wlst,
   695                                const w_char* word,
   696                                int wl,
   697                                int cpdsuggest) {
   698    std::vector<w_char> candidate_utf(word, word + wl);
   699    if (candidate_utf.size() < 2)
   700      return wlst.size();
   701    // try omitting one char of word at a time
   702    for (size_t i = 0; i < candidate_utf.size(); ++i) {
   703      size_t index = candidate_utf.size() - 1 - i;
   704      w_char tmpc = candidate_utf[index];
   705      candidate_utf.erase(candidate_utf.begin() + index);
   706      std::string candidate;
   707      u16_u8(candidate, candidate_utf);
   708      testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   709      candidate_utf.insert(candidate_utf.begin() + index, tmpc);
   710    }
   711    return wlst.size();
   712  }
