   933  // error is adjacent letter were swapped
   934  int SuggestMgr::swapchar_utf(std::vector<std::string>& wlst,
   935                               const w_char* word,
   936                               int wl,
   937                               int cpdsuggest) {
   938    std::vector<w_char> candidate_utf(word, word + wl);
   939    if (candidate_utf.size() < 2)
   940      return wlst.size();
   941
   942    std::string candidate;
   943    // try swapping adjacent chars one by one
   944    for (size_t i = 0; i < candidate_utf.size() - 1; ++i) {
   945      std::swap(candidate_utf[i], candidate_utf[i+1]);
   946      u16_u8(candidate, candidate_utf);
   947      testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   948      std::swap(candidate_utf[i], candidate_utf[i+1]);
   949    }
   950
   951    // try double swaps for short words
   952    // ahev -> have, owudl -> would, suodn -> sound
   953    if (candidate_utf.size() == 4 || candidate_utf.size() == 5) {
   954      candidate_utf[0] = word[1];
   955      candidate_utf[1] = word[0];
   956      candidate_utf[2] = word[2];
   957      candidate_utf[candidate_utf.size() - 2] = word[candidate_utf.size() - 1];
   958      candidate_utf[candidate_utf.size() - 1] = word[candidate_utf.size() - 2];
   959      u16_u8(candidate, candidate_utf);
   960      testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   961      if (candidate_utf.size() == 5) {
   962        candidate_utf[0] = word[0];
   963        candidate_utf[1] = word[2];
   964        candidate_utf[2] = word[1];
   965        u16_u8(candidate, candidate_utf);
   966        testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   967      }
   968    }
   969    return wlst.size();
   970  }
