   972  // error is not adjacent letter were swapped
   973  int SuggestMgr::longswapchar(std::vector<std::string>& wlst,
   974                               const char* word,
   975                               int cpdsuggest) {
   976    std::string candidate(word);
   977    // try swapping not adjacent chars one by one
   978    for (std::string::iterator p = candidate.begin(); p < candidate.end(); ++p) {
   979      for (std::string::iterator q = candidate.begin(); q < candidate.end(); ++q) {
   980        size_t distance = std::abs(std::distance(q, p));
   981        if (distance > 1 && distance <= MAX_CHAR_DISTANCE) {
   982          std::swap(*p, *q);
   983          testsug(wlst, candidate, cpdsuggest, NULL, NULL);
   984          std::swap(*p, *q);
